// Example of a platform detection method in an Ionic Angular component
detectPlatform() {
  const platform = Capacitor.getPlatform();
  this.isWeb = platform === 'web';
  this.isIOS = platform === 'ios';
  this.isAndroid = platform === 'android';
}

